  replace(/[?&](?:key|token|secret|password|code|api_key|access_token)=[^\s&#<>"']+/gi, '[REDACTED:query_secret]');
  replace(/[A-Za-z0-9.+_-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[REDACTED:email]');
